import sys
from collections import defaultdict

def normalize(hostname):
    return hostname.rstrip('/')

def main():
    input = sys.stdin.read
    data = input().splitlines()

    n = int(data[0])
    hostnames = data[1:]

    normalized_hostnames = [normalize(hostname) for hostname in hostnames]

    groups = defaultdict(set)
    for hostname in normalized_hostnames:
        groups[hostname].add(hostname)

    for i in range(n):
        for j in range(i + 1, n):
            if normalized_hostnames[i] != normalized_hostnames[j]:
                if all(normalized_hostnames[i] in groups[normalized_hostnames[j]] for _ in range(n)):
                    groups[normalized_hostnames[i]].update(groups[normalized_hostnames[j]])
                    groups[normalized_hostnames[j]] = groups[normalized_hostnames[i]]

    result = []
    for group in groups.values():
        if len(group) > 1:
            result.append(' '.join(group))

    print(len(result))
    for line in result:
        print(line)

if __name__ == "__main__":
    main()

MOD = 10**9 + 7

def count_paths(n, m, labyrinth):
    dp = [[0] * m for _ in range(n)]
    dp[0][0] = 1

    for i in range(n):
        for j in range(m):
            if labyrinth[i][j] == 'R':
                continue
            if i > 0:
                dp[i][j] = (dp[i][j] + dp[i-1][j]) % MOD
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i][j-1]) % MOD

    return dp[n-1][m-1]

