import sys
from collections import defaultdict

def main():
    input = sys.stdin.read
    data = input().split()
    l = int(data[0])
    r = int(data[1])

    divisor_count = defaultdict(int)

    for num in range(l, r + 1):
        for i in range(2, num + 1):
            if num % i == 0:
                divisor_count[i] += 1

    max_divisor = max(divisor_count, key=divisor_count.get)
    print(max_divisor)

if __name__ == "__main__":
    main()
